 TextBlock Text(string text,double size,bool bold=false){return Theme.Text(text,size,bold?ink:muted,bold);}
 Border Card(UIElement content){return new GlassCard{Background=panel,BorderBrush=line,BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(22),Padding=new Thickness(18),Margin=new Thickness(0,0,0,12),Child=content};}
 Button Button(string text,bool primary=false){return dark?Dark.Button(text):Theme.Button(text,primary);}
 void ChangeTheme(bool value){try{AppSettings.SetNight(value);}catch(Exception ex){AppDialog.Show(this,"外观保存失败："+ex.Message,"设置");}}
 void RefreshTheme(){if(lightMode==null)return;if(chinese!=null){chinese.Background=L.English?panel:Theme.Pale;english.Background=L.English?Theme.Pale:panel;chinese.BorderBrush=L.English?line:accent;english.BorderBrush=L.English?accent:line;}lightMode.BorderThickness=nightMode.BorderThickness=new Thickness(1);lightMode.Background=AppSettings.Night?panel:Theme.Pale;nightMode.Background=AppSettings.Night?Theme.Pale:panel;lightMode.BorderBrush=AppSettings.Night?line:accent;nightMode.BorderBrush=AppSettings.Night?accent:line;RefreshFont();foreach(var b in interfaceChoices){bool selected=(string)b.Tag=="ui-font:"+AppSettings.InterfaceFont;b.BorderBrush=selected?accent:line;b.Background=selected?Theme.Pale:panel;}}
 void ChooseInterfaceFont(int value){try{AppSettings.SetInterfaceFont(value);}catch(Exception ex){AppDialog.Show(this,"界面字号保存失败："+ex.Message,"设置");}}
 void ChooseFont(int size){try{AppSettings.SetFont(size);RefreshFont();}catch(Exception ex){AppDialog.Show(this,"字号保存失败："+ex.Message,"设置");}}
 void RefreshFont(){if(fontPreview==null)return;fontPreview.FontSize=AppSettings.EditorFont;foreach(var b in fontChoices){bool selected=(int)b.Tag==AppSettings.EditorFont;b.Background=selected?(dark?Theme.B("#315E8A"):Theme.B("#DCEBFF")):(dark?Theme.B("#1A2B43"):Theme.White);b.Foreground=selected?(dark?Theme.B("#F0F7FF"):Theme.Blue):ink;b.BorderBrush=selected?accent:line;}}
 void SaveAuto(bool value){try{AppSettings.SetAutoCheck(value);}catch(Exception ex){downloadState.Text="设置保存失败："+ex.Message;}}
 void Open(string target){try{Process.Start(new ProcessStartInfo(target){UseShellExecute=true});}catch(Exception ex){downloadState.Text="无法打开："+ex.Message;}}
 void OnUpdate(){if(!closed&&!Dispatcher.HasShutdownStarted)Dispatcher.BeginInvoke((Action)Refresh);}
 public void Refresh(){var latest=UpdateService.Latest;updateState.Text=UpdateService.Checking?"正在连接 GitHub Release…":UpdateService.Status;lastCheck.Text=UpdateService.CheckedAt==DateTime.MinValue?"自动检查不影响离线编程与评测。":"上次成功检查："+UpdateService.CheckedAt.ToString("yyyy-MM-dd HH:mm");check.IsEnabled=!downloading&&!UpdateService.Checking;install.IsEnabled=!downloading&&!UpdateService.Checking&&latest!=null&&latest.CanInstall;releaseTitle.Visibility=notes.Visibility=latest!=null&&latest.Newer?Visibility.Visible:Visibility.Collapsed;releaseTitle.Text=latest!=null&&latest.Newer?"可用版本 ver"+latest.VersionText:"";notes.Text=latest!=null&&latest.Newer?latest.Notes:"";}
 async Task CheckNow(){if(preview){downloadState.Text="预览模式未联网。";return;}await UpdateService.Check(true);if(!closed)Refresh();}
 async Task Install(){var release=UpdateService.Latest;if(release==null||!release.CanInstall||downloading)return;if(!UpdateService.CanRestart){downloadState.Text="请先结束当前闯关或评测，再进行更新。";return;}downloading=true;download=new CancellationTokenSource(TimeSpan.FromMinutes(10));cancel.Visibility=progress.Visibility=Visibility.Visible;Refresh();try{downloadState.Text="正在下载并检查文件…";string file=await UpdateService.Download(release,new Progress<int>(v=>{if(!closed){progress.Value=v;downloadState.Text="正在下载 "+v+"% · 完成后校验并重启";}}),download.Token);downloadState.Text="校验通过，准备重启…";downloading=false;UpdateService.PrepareAndRestart(file,release);}catch(OperationCanceledException){downloadState.Text="下载已取消或超时，可重新尝试。";}catch(Exception ex){downloadState.Text="更新未完成："+ex.Message+"\n请检查网络或文件占用后重试；需要写入受保护目录时，软件会申请系统授权。";}finally{downloading=false;download.Dispose();download=null;cancel.Visibility=progress.Visibility=Visibility.Collapsed;if(!closed)Refresh();}}
